parameters.jsCode:
const payload = $input.first().json ?? {};

const execution = payload.execution ?? {};
const trigger = payload.trigger ?? {};
const workflow = payload.workflow ?? {};

const error =
  execution.error
  ?? trigger.error
  ?? {};

const cause =
  error.cause
  ?? {};

const workflowName = String(
  workflow.name
  ?? 'Workflow desconocido'
);

const workflowId = String(
  workflow.id
  ?? ''
);

const workflowCodeMatch =
  workflowName
    .toUpperCase()
    .match(/\bWF-\d{3}\b/);

const workflowCode =
  workflowCodeMatch?.[0]
  ?? 'UNKNOWN';

const sourceCodes = {
  'WF-001':
    'SECOP_II_PROCESSES',

  'WF-002':
    'SECOP_II_PROCESS_VERSIONS',

  'WF-003':
    'SECOP_II_DOCUMENTS_2025',

  'WF-005':
    'SECOP_II_PROFILE_MATCHES',

  'WF-014':
    'SECOP_OPPORTUNITY_DOCUMENT_EXTRACTION',

  'WF-015':
    'SECOP_OPPORTUNITY_REQUIREMENT_EXTRACTION',

  'WF-016':
  'SECOP_OPPORTUNITY_REQUIREMENT_CONSOLIDATION',

  'WF-012':
  'SECOP_ORGANIZATION_DOCUMENT_VALIDITY',

  'WF-017':
    'SECOP_OPPORTUNITY_COMPLIANCE_EVALUATION',

  'WF-018':
  'SECOP_OPPORTUNITY_ACTION_PLAN_GENERATION',

  'WF-019':
  'SECOP_PIPELINE_ORCHESTRATION',
};

const sourceCode =
  sourceCodes[workflowCode]
  ?? '';

const originalExecutionId =
  execution.id
    ? String(execution.id)
    : '';

const fallbackExecutionId =
  `trigger-${workflowCode}-${String(
    workflowId || 'unknown'
  )}-${Date.now()}`;

const failedExecutionId =
  originalExecutionId
  || fallbackExecutionId;

const errorMessage = String(
  error.message
  ?? cause.message
  ?? 'Error sin mensaje informado por n8n'
);

const errorStack = String(
  error.stack
  ?? cause.stack
  ?? ''
);

const lastNodeExecuted = String(
  execution.lastNodeExecuted
  ?? error.node?.name
  ?? 'trigger_or_unknown'
);

const executionMode = String(
  execution.mode
  ?? trigger.mode
  ?? 'unknown'
);

const executionUrl = String(
  execution.url
  ?? ''
);

const retryOf = String(
  execution.retryOf
  ?? ''
);

const limitedMessage =
  errorMessage.slice(0, 10000);

const limitedStack =
  errorStack.slice(0, 50000);

const safeJsonStringify = (value) => {
  const seen = new WeakSet();

  return JSON.stringify(
    value,
    (_key, currentValue) => {
      if (typeof currentValue === 'bigint') {
        return currentValue.toString();
      }

      if (
        currentValue
        && typeof currentValue === 'object'
      ) {
        if (seen.has(currentValue)) {
          return '[Circular]';
        }

        seen.add(currentValue);
      }

      return currentValue;
    }
  );
};

const errorDetailsJson =
  safeJsonStringify({
    stack:
      limitedStack || null,

    raw_error:
      payload,
  });

const runMetadataJson =
  safeJsonStringify({
    workflow_code:
      workflowCode || 'UNKNOWN',

    workflow_name:
      workflowName,

    workflow_id:
      workflowId || null,

    source_code:
      sourceCode || null,

    execution_url:
      executionUrl || null,

    retry_of:
      retryOf || null,

    handled_by:
      'WF-007',

    handled_at:
      new Date().toISOString(),
  });

const cursorMetadataJson =
  safeJsonStringify({
    workflow_code:
      workflowCode || 'UNKNOWN',

    last_error_execution_id:
      failedExecutionId,

    last_error_node:
      lastNodeExecuted,

    last_error_message:
      limitedMessage,

    last_error_at:
      new Date().toISOString(),

    error_handled_by:
      'WF-007',
  });

return [
  {
    json: {
      workflow_code:
        workflowCode,

      source_code:
        sourceCode,

      failed_execution_id:
        failedExecutionId,

      original_execution_id:
        originalExecutionId,

      has_execution_id:
        Boolean(originalExecutionId),

      workflow_name:
        workflowName,

      workflow_id:
        workflowId,

      execution_mode:
        executionMode,

      execution_url:
        executionUrl,

      retry_of:
        retryOf,

      last_node_executed:
        lastNodeExecuted,

      error_message:
        limitedMessage,

      error_stack:
        limitedStack,

      raw_error:
        payload,

      error_details_json:
        errorDetailsJson,

      run_metadata_json:
        runMetadataJson,

      cursor_metadata_json:
        cursorMetadataJson,

      query_parameters: [
        workflowCode || 'UNKNOWN',
        sourceCode || null,
        failedExecutionId,
        executionMode || null,
        lastNodeExecuted || null,
        limitedMessage || null,
        errorDetailsJson,
        runMetadataJson,
        originalExecutionId || null,
        cursorMetadataJson,
      ],
    },
  },
];
